package com.profitness.dsa;

import java.util.ArrayList;

/**
 * Encapsulates the results, metrics, and step-by-step diagnostic trace
 * generated by running a sorting algorithm on an array of {@link MemberNode} records.
 * <p>
 * <b>Data Structure & Algorithmic Role:</b><br>
 * Transports the newly sorted member array alongside metrics such as total comparisons,
 * swaps/merge operations, wall-clock execution time in nanoseconds, and human-readable steps.
 * </p>
 * <p>
 * <b>Time Complexity:</b><br>
 * O(1) for metric access and array retrieval.
 * </p>
 * <p>
 * <b>Gym Application:</b><br>
 * Allows gym managers and developers to benchmark sorting techniques (Insertion Sort vs Merge Sort)
 * when organizing member directories by ID for reporting, billing, or pre-processing for binary search.
 * </p>
 */
public class SortResult {
    private String algorithmName;
    private MemberNode[] sortedArray;
    private int comparisons;
    private int swapsOrMerges;
    private ArrayList<String> steps;
    private long timeNanos;

    /**
     * Default constructor for progressive computation during recursive sorts.
     */
    public SortResult() {
        this.algorithmName = "";
        this.sortedArray = new MemberNode[0];
        this.comparisons = 0;
        this.swapsOrMerges = 0;
        this.steps = new ArrayList<>();
        this.timeNanos = 0;
    }

    /**
     * Constructs a SortResult with known algorithm name and target array.
     *
     * @param algorithmName Name of the sorting algorithm
     * @param sortedArray   Initial reference to the array
     */
    public SortResult(String algorithmName, MemberNode[] sortedArray) {
        this.algorithmName = algorithmName;
        this.sortedArray = sortedArray;
        this.comparisons = 0;
        this.swapsOrMerges = 0;
        this.steps = new ArrayList<>();
        this.timeNanos = 0;
    }

    /**
     * Constructs a fully initialized SortResult record.
     *
     * @param algorithmName Name of the sorting algorithm ("Insertion Sort" or "Merge Sort")
     * @param sortedArray   The resulting array sorted in ascending order of memberID
     * @param comparisons   Total number of key comparison operations executed
     * @param swapsOrMerges Total number of element shift/swap or merge operations executed
     * @param steps         Detailed chronological trace entries explaining each sorting phase
     * @param timeNanos     Wall-clock execution duration in nanoseconds
     */
    public SortResult(String algorithmName, MemberNode[] sortedArray, int comparisons,
                      int swapsOrMerges, ArrayList<String> steps, long timeNanos) {
        this.algorithmName = algorithmName;
        this.sortedArray = sortedArray;
        this.comparisons = comparisons;
        this.swapsOrMerges = swapsOrMerges;
        this.steps = steps != null ? steps : new ArrayList<>();
        this.timeNanos = timeNanos;
    }

    /**
     * @return the sorted array of MemberNode elements
     */
    public MemberNode[] getSortedArray() {
        return sortedArray;
    }

    public void setSortedArray(MemberNode[] sortedArray) {
        this.sortedArray = sortedArray;
    }

    /**
     * @return the total number of comparisons performed
     */
    public int getComparisons() {
        return comparisons;
    }

    public void setComparisons(int comparisons) {
        this.comparisons = comparisons;
    }

    public void incrementComparisons() {
        this.comparisons++;
    }

    /**
     * @return the total number of shift/swap or merge operations performed
     */
    public int getSwapsOrMerges() {
        return swapsOrMerges;
    }

    public void setSwapsOrMerges(int swapsOrMerges) {
        this.swapsOrMerges = swapsOrMerges;
    }

    public void incrementSwapsOrMerges() {
        this.swapsOrMerges++;
    }

    /**
     * @return visual list of execution steps recorded during the sort
     */
    public ArrayList<String> getSteps() {
        return steps;
    }

    public void setSteps(ArrayList<String> steps) {
        this.steps = steps != null ? steps : new ArrayList<>();
    }

    public void addStep(String step) {
        if (this.steps == null) {
            this.steps = new ArrayList<>();
        }
        this.steps.add(step);
    }

    /**
     * @return execution duration in nanoseconds
     */
    public long getTimeNanos() {
        return timeNanos;
    }

    public void setTimeNanos(long timeNanos) {
        this.timeNanos = timeNanos;
    }

    /**
     * @return execution duration in fractional milliseconds
     */
    public double getTimeMillis() {
        return timeNanos / 1_000_000.0;
    }

    /**
     * @return the name of the sorting algorithm
     */
    public String getAlgorithmName() {
        return algorithmName;
    }

    public void setAlgorithmName(String algorithmName) {
        this.algorithmName = algorithmName;
    }

    @Override
    public String toString() {
        return String.format("[%s] Size: %d | Comparisons: %d | Swaps/Merges: %d | Time: %.4f ms",
                algorithmName, (sortedArray != null ? sortedArray.length : 0),
                comparisons, swapsOrMerges, getTimeMillis());
    }
}
